CREATE TABLE ledger_period_closures (
 id char(36) NOT NULL COMMENT '회계기간 마감 고유번호', company_id varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '마감 대상 회사', fiscal_year smallint unsigned NOT NULL COMMENT '마감 회계연도', period_start_date date NOT NULL COMMENT '마감기간 시작일', period_end_date date NOT NULL COMMENT '마감기간 종료일', close_status_code varchar(20) NOT NULL DEFAULT 'OPEN' COMMENT '마감상태(OPEN,CLOSED,REOPENED)', current_revision int unsigned NOT NULL DEFAULT 0 COMMENT '현재 마감 Revision', close_reason varchar(500) DEFAULT NULL COMMENT '마감 사유', closed_at datetime DEFAULT NULL COMMENT '최근 마감일시', closed_by varchar(100) DEFAULT NULL COMMENT '최근 마감 Actor', reopened_at datetime DEFAULT NULL COMMENT '최근 재개방일시', reopened_by varchar(100) DEFAULT NULL COMMENT '최근 재개방 Actor', reopen_reason varchar(500) DEFAULT NULL COMMENT '최근 재개방 사유', created_at datetime NOT NULL DEFAULT current_timestamp() COMMENT '생성일시', created_by varchar(100) NOT NULL COMMENT '생성 Actor', updated_at datetime DEFAULT NULL COMMENT '수정일시', updated_by varchar(100) DEFAULT NULL COMMENT '수정 Actor', PRIMARY KEY(id), UNIQUE KEY uk_ledger_period_closures_company_year(company_id,fiscal_year), KEY idx_ledger_period_closures_status(close_status_code,period_end_date), CONSTRAINT fk_ledger_period_closures_company FOREIGN KEY(company_id) REFERENCES system_company(id), CONSTRAINT chk_ledger_period_closures_period CHECK(period_start_date<=period_end_date), CONSTRAINT chk_ledger_period_closures_status CHECK(close_status_code IN ('OPEN','CLOSED','REOPENED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='회사·회계연도별 현재 결산 마감상태 SSOT';

CREATE TABLE ledger_period_closure_histories (
 id char(36) NOT NULL COMMENT '결산 마감이력 고유번호', period_closure_id char(36) NOT NULL COMMENT '회계기간 마감 원본', revision_no int unsigned NOT NULL COMMENT '마감 Revision 번호', action_code varchar(20) NOT NULL COMMENT '결산 작업(CLOSE,REOPEN)', reason varchar(500) NOT NULL COMMENT '마감 또는 재개방 사유', readiness_snapshot_json json NOT NULL COMMENT '처리 당시 결산점검 결과 Snapshot', processed_at datetime NOT NULL COMMENT '처리일시', processed_by varchar(100) NOT NULL COMMENT '처리 Actor', PRIMARY KEY(id), UNIQUE KEY uk_ledger_period_closure_history_revision(period_closure_id,revision_no), CONSTRAINT fk_ledger_period_closure_history_parent FOREIGN KEY(period_closure_id) REFERENCES ledger_period_closures(id) ON DELETE CASCADE, CONSTRAINT chk_ledger_period_closure_history_action CHECK(action_code IN ('CLOSE','REOPEN'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='결산 마감·재개방의 불변 Revision 감사이력';
